MonthlyCost.custom_check_code:
def custom_check(series: pd.Series) -> dict:
    import re
    pattern = re.compile(r'^\d+(\.\d+)?$')
    total = len(series)
    mask = ~series.astype(str).apply(lambda x: bool(pattern.fullmatch(x.strip())))
    violations = series[mask]
    count = len(violations)
    if count == 0:
        return {"passed": True, "metric": "0 violations", "details": "All values conform to quality constraint"}
    else:
        sample = ', '.join(map(str, violations.head(5).tolist()))
        return {"passed": False, "metric": f"{count} / {total} violations", "details": f"Non-conforming values: {sample}"}}

SignupDate.custom_check_code:
def custom_check(series: pd.Series) -> dict:
    pattern = r'^\d{4}-\d{2}-\d{2}$'
    violations = []
    for idx, val in series.items():
        if not isinstance(val, str) or not re.match(pattern, val):
            violations.append(idx)
        else:
            try:
                pd.to_datetime(val, format='%Y-%m-%d', errors='raise')
            except Exception:
                violations.append(idx)
    if violations:
        return {"passed": False, "metric": f"{len(violations)} / {len(series)} violations", "details": f"Violations at indices: {violations}"}
    return {"passed": True, "metric": "0 violations", "details": "All values conform to quality constraint"}

IsActive.custom_check_code:
def custom_check(series: pd.Series) -> dict:
    total = len(series)
    mask = series.str.lower().isin(['yes','no'])
    violations = total - mask.sum()
    if violations:
        bad = series[~mask].head(5).to_dict()
        details = f"Found {violations} non-conforming values: {bad}"
        return {"passed": False, "metric": f"{violations} / {total} violations", "details": details}
    return {"passed": True, "metric": "0 violations", "details": "All values conform to quality constraint"}
